  (154103, 0, 0, 'This gonna be off hook!', 12, 0, 100, 0, 0, 0, 0, 0, 'Ogre Chef'),
  (154103, 1, 0, 'Me gonna take everyone on ride to flavor... flavor... uh. Flavor place!', 12, 0, 100, 0, 0, 0, 0, 0, 'Ogre Chef'),
