  (154327, 1, 0, 'I''ve taught you the basics. Now find a beast and tame it.', 12, 0, 100, 0, 0, 0, 190163, 0, 'Austin Huxworth'),
  (156280, 0, 0, 'Private Cole will run you through the rest of the drills. I need to discuss this storm with the helmsman.', 12, 0, 100, 0, 0, 0, 184106, 0, 'Captain Garrick'),
  (156280, 1, 0, 'Everyone below decks! Now!', 12, 0, 100, 0, 0, 0, 177674, 0, 'Captain Garrick'),
  (156626, 0, 0, '$n! Thank the Light! Are you injured?', 12, 0, 100, 3, 0, 0, 178506, 0, 'Captain Garrick'),
  (156676, 0, 0, 'New sacrifice!', 12, 0, 100, 0, 0, 0, 178950, 0, 'Ogre Overseer aggro'),
