  (156891, 0, 0, 'All right, let''s see what we can find.', 12, 0, 100, 0, 0, 0, 178906, 0, 'Bjorn Stouthands to Player'),
  (156891, 1, 0, 'Well... I think we can say we found somethin''.', 12, 0, 100, 0, 0, 0, 178907, 0, 'Bjorn Stouthands to Player'),
  (157300, 0, 0, '|TINTERFACE\\ICONS\\Ability_Earthen_Pillar.blp:20|t Avoid Tunk''s |cFFFF0404|Hspell:308463|h[Seismic Slam]|h|r by moving to the left or right!', 42, 0, 100, 0, 0, 0, 0, 0, 'Tunk to Player'),
  (157300, 1, 0, '|TINTERFACE\\ICONS\\WARRIOR_DISRUPTINGSHOUT.BLP:20|t Some spells can interrupt your casting. Stop casting to avoid being interrupted by |cFFFF0404|Hspell:321240|h[Interrupting Shout]|h|r!', 42, 0, 100, 0, 0, 0, 0, 0, 'Tunk to Player'),
  (160664, 0, 0, 'Captain! We can''t weather this storm for long!', 12, 0, 100, 0, 0, 0, 177675, 0, 'Private Cole'),
  (162817, 0, 0, 'We take soul for ritual, you no stop!', 12, 0, 100, 0, 0, 0, 0, 0, 'Torgok aggro'),
  (162817, 1, 0, 'Me never get... to see... ritual...', 12, 0, 100, 0, 0, 0, 0, 0, 'Torgok death'),
  (166583, 0, 0, 'Warlord! This storm will soon overwhelm us!', 12, 0, 100, 0, 0, 0, 195892, 0, 'Grunt Throg'),
  (166782, 0, 0, '$n! You survived! We need to regroup at once.', 12, 0, 100, 3, 0, 0, 195918, 0, 'Warlord Breka Grimaxe'),
  (166787, 0, 0, 'My thanks. We''ll find the expedition yet.', 12, 0, 100, 0, 0, 0, 195930, 0, 'Bo'),
  (166792, 0, 0, 'Mark my words, that storm was unnatural.', 12, 0, 100, 0, 0, 0, 195932, 0, 'Mithdran Dawntracker'),
  (166797, 0, 0, 'Quite the storm. Probably hit the first boat, too.', 12, 0, 100, 0, 0, 0, 195924, 0, 'Lana Jordan'),
  (166824, 0, 0, 'Throg will spar with you for now. I must speak to the crew about the rain.', 12, 0, 100, 0, 0, 0, 199040, 0, 'Warlord Breka Grimaxe'),
  (166827, 1, 0, 'Soldiers, brace yourselves!', 12, 0, 100, 0, 0, 0, 195893, 0, 'Warlord Breka Grimaxe'),
  (166996, 0, 0, 'That shall have to do for now. Find a beast and tame it.', 12, 0, 100, 0, 0, 0, 196683, 0, 'Mithdran Dawntracker'),
  (167225, 0, 0, 'Let''s see if we can find one of those rituals.', 12, 0, 100, 0, 0, 0, 196409, 0, 'Lana Jordan to Player'),
